<?php require 'partials.php';$games=db()->query("SELECT * FROM games WHERE status IN ('live','completed') ORDER BY CASE status WHEN 'live' THEN 0 ELSE 1 END, updated_at DESC, play_date DESC,play_time DESC LIMIT 20")->fetchAll();header_html('Live results','live');?><script>document.body.dataset.refresh='live'</script><section class="card"><div class="section-title"><div><h1>Live results</h1><p class="muted">Automatically refreshes every 15 seconds.</p></div><span class="status live"><span class="live-dot"></span>LIVE</span></div><?php if(!$games):?><p class="notice">No live or completed games are available yet.</p><?php endif;foreach($games as $g):?><article class="match"><div><b><?=$g['play_time']?></b><br><small class="muted">#<?=$g['game_no']?></small></div><div><div class="match-team"><b><?=h($g['team1'])?></b><span class="score"><?=is_null($g['score1'])?'–':$g['score1']?></span></div><div class="match-team"><b><?=h($g['team2'])?></b><span class="score"><?=is_null($g['score2'])?'–':$g['score2']?></span></div><small class="muted"><?=h($g['field'])?> · <?=h($g['phase'])?></small></div><?=status_badge($g['status'])?></article><?php endforeach;?></section><?php footer_html();?>